import{_ as a,o as t,c as s,am as i}from"./chunks/framework.yj4qiWdr.js";const h=JSON.parse('{"title":"Validation et preuves","description":"","frontmatter":{"title":"Validation et preuves","aside":true,"prev":false,"next":false},"headers":[],"relativePath":"bug-bounty/validation.md","filePath":"bug-bounty/validation.md"}'),r={name:"bug-bounty/validation.md"};function n(l,e,o,u,p,d){return t(),s("div",null,e[0]||(e[0]=[i('<h1 id="validation-et-preuves" tabindex="-1">Validation et preuves <a class="header-anchor" href="#validation-et-preuves" aria-label="Permalink to &quot;Validation et preuves&quot;">​</a></h1><p><a href="./">Retour au parcours</a></p><p>Objectif : confirmer manuellement les observations, documenter le résultat et démontrer uniquement l&#39;impact nécessaire.</p><h2 id="analyse-et-validation" tabindex="-1">Analyse et validation <a class="header-anchor" href="#analyse-et-validation" aria-label="Permalink to &quot;Analyse et validation&quot;">​</a></h2><ul><li>Examiner les comportements communs, puis les différences entre applications et fonctionnalités.</li><li>Contrôler manuellement les résultats automatisés ; une réponse HTTP 200 ou une chaîne réfléchie ne suffit pas à démontrer une vulnérabilité.</li><li>Utiliser des comptes de test et des données fictives ; ne pas réutiliser de secrets découverts.</li><li>Démontrer uniquement l&#39;impact nécessaire, sans accéder à des données réelles non nécessaires.</li></ul><h2 id="proof-of-concept-poc" tabindex="-1">Proof of Concept (PoC) <a class="header-anchor" href="#proof-of-concept-poc" aria-label="Permalink to &quot;Proof of Concept (PoC)&quot;">​</a></h2><ul><li>Documenter le contexte, les prérequis et les étapes reproductibles.</li><li>Joindre les requêtes et réponses pertinentes, captures ou vidéo de démonstration.</li><li>Masquer les secrets et données personnelles.</li></ul><h2 id="empreinte-des-fichiers-de-preuve" tabindex="-1">Empreinte des fichiers de preuve <a class="header-anchor" href="#empreinte-des-fichiers-de-preuve" aria-label="Permalink to &quot;Empreinte des fichiers de preuve&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> preuves/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> preuves.sha256</span></span></code></pre></div><p>Calcule les empreintes des fichiers de preuve locaux pour documenter leur intégrité. Ne conserver que des preuves expurgées ; ajout de documentation locale.</p><h2 id="avant-de-poursuivre" tabindex="-1">Avant de poursuivre <a class="header-anchor" href="#avant-de-poursuivre" aria-label="Permalink to &quot;Avant de poursuivre&quot;">​</a></h2><ul><li>Impact démontré et étapes de reproduction documentées.</li><li>Preuves expurgées et enregistrées.</li></ul><hr><p><a href="./vulnerabilites">Précédent : Tests de vulnérabilités</a> · <a href="./">Parcours</a> · <a href="./rapport">Suivant : Rapport et signalement</a></p>',14)]))}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
